#include <bits/stdc++.h>
using namespace std;
int main() {
    int n; cin >> n;
    auto isPrime = [](int x) { if (x < 2) return false; for (int d = 2; d * d <= x; d++) if (x % d == 0) return false; return true; };
    int p = n; while (!isPrime(p)) p++;
    int need = (p - n);           // chords to add: each adds 2 to degree sum, so need/... see below
    // start with a Hamiltonian cycle (all degrees 2, m = n); add k/2 chords with k = 2*(p-n) endpoints of degree 3
    vector<pair<int, int>> e;
    vector<vector<bool>> adj(n + 1, vector<bool>(n + 1, false));
    for (int i = 1; i <= n; i++) { int j = i % n + 1; e.push_back({i, j}); adj[i][j] = adj[j][i] = true; }
    vector<bool> used(n + 1, false);
    int chords = need;            // p-n chords -> m = n + (p-n) = p edges, all degrees 2 or 3
    for (int x = 1; x <= n && chords > 0; x++) {
        if (used[x]) continue;
        for (int y = x + 1; y <= n; y++) {
            if (used[y] || adj[x][y]) continue;
            used[x] = used[y] = true; adj[x][y] = adj[y][x] = true;
            e.push_back({x, y}); chords--;
            break;
        }
    }
    cout << e.size() << "\n";
    for (auto [u, v] : e) cout << u << " " << v << "\n";
}

