string add(const string &a, const string &b) {
    string r; int i = a.size() - 1, j = b.size() - 1, c = 0;
    while (i >= 0 || j >= 0 || c) {
        int s = c;
        if (i >= 0) s += a[i--] - '0';
        if (j >= 0) s += b[j--] - '0';
        r.push_back('0' + s % 10); c = s / 10;
    }
    reverse(r.begin(), r.end());
    return r;
}
bool lessNum(const string &a, const string &b) {
    if (a.size() != b.size()) return a.size() < b.size();
    return a < b;
}
int main() {
    int l; string s;
    cin >> l >> s;
    int n = s.size(), mid = n / 2;
    vector<int> cand;
    for (int i = mid; i >= 1; i--) if (s[i] != '0') { cand.push_back(i); break; }
    for (int i = mid + 1; i < n; i++) if (s[i] != '0') { cand.push_back(i); break; }
    string best;
    for (int i : cand) {
        string r = add(s.substr(0, i), s.substr(i));
        if (best.empty() || lessNum(r, best)) best = r;
    }
