// parse a decimal with up to 5 fractional digits exactly, scaled by 1e5
long long parse(const string &s) {
    bool neg = s[0] == '-';
    size_t st = (s[0] == '-' || s[0] == '+') ? 1 : 0;
    long long ip = 0, fp = 0; int fd = 0; bool dot = false;
    for (size_t i = st; i < s.size(); i++) {
        if (s[i] == '.') { dot = true; continue; }
        if (!dot) ip = ip * 10 + (s[i] - '0');
        else if (fd < 5) { fp = fp * 10 + (s[i] - '0'); fd++; }
    }
    while (fd < 5) { fp *= 10; fd++; }
    long long v = ip * 100000 + fp;
    return neg ? -v : v;
}
int main() {
    const long long S = 100000;
    int n; cin >> n;
    vector<long long> V(n), fl(n);
    for (auto &v : V) { string s; cin >> s; v = parse(s); }
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        long long v = V[i];
        fl[i] = v >= 0 ? v / S : -((-v + S - 1) / S);
        sum += fl[i];
    }
    long long need = -sum;
    for (int i = 0; i < n && need > 0; i++)
        if (V[i] % S != 0) { fl[i]++; need--; }
    for (auto f : fl) cout << f << "\n";
}

