        int n; scanf("%d", &n);
        vector<int> p(n);
        for (auto &x : p) scanf("%d", &x);
        // vb[c] (1<=c<n): a valid boundary after the first c participants
        vector<bool> vb(n + 1, false);
        for (int c = 1; c < n; c++) vb[c] = p[c - 1] > p[c];
        vector<int> pc(n + 1, 0);
        for (int c = 1; c <= n; c++) pc[c] = pc[c - 1] + (c < n && vb[c]);
        int H = n / 2, g = -1;
        for (int c = 1; c < n; c++) if (vb[c]) { g = c; break; }
        bool found = false;
        for (int c3 = H; c3 >= 1 && g != -1 && !found; c3--) {
            if (!vb[c3]) continue;
            int lo = 2 * g + 1, hi = c3 - g - 1;
            if (lo > hi || pc[hi] - pc[lo - 1] == 0) continue;
            int c2 = -1;
            for (int c = lo; c <= hi; c++) if (vb[c]) { c2 = c; break; }
            printf("%d %d %d\n", g, c2 - g, c3 - c2);
            found = true;
        }
        if (!found) printf("0 0 0\n");
    }
}

