#include <bits/stdc++.h>
using namespace std; typedef long long ll;
struct E { int u, v; ll w; }; const ll INF = LLONG_MAX;  // Chu-Liu/Edmonds, -1 if impossible
ll dmst(int n, int r, vector<E> es) {
    ll res = 0;
    while (true) {
        vector<ll> in(n, INF); vector<int> pre(n, -1), id(n, -1), vis(n, -1);
        for (auto &e : es) if (e.u != e.v && e.w < in[e.v]) in[e.v] = e.w, pre[e.v] = e.u;
        for (int i = 0; i < n; i++) if (i != r && in[i] == INF) return -1;
        int cnt = 0; in[r] = 0;
        for (int i = 0; i < n; i++) {
            res += in[i];
            int v = i;
            while (vis[v] != i && id[v] == -1 && v != r) vis[v] = i, v = pre[v];
            if (v != r && id[v] == -1) {
                for (int u = pre[v]; u != v; u = pre[u]) id[u] = cnt;
                id[v] = cnt++;
            }
        }
        if (cnt == 0) break;
        for (int i = 0; i < n; i++) if (id[i] == -1) id[i] = cnt++;
        for (auto &e : es) { int v = e.v; e.u = id[e.u]; e.v = id[e.v]; if (e.u != e.v) e.w -= in[v]; }
        n = cnt; r = id[r];
    }
    return res;
}
int main() {
    const ll BIG = 1000000000000LL;   // virtual root edges; BIG exceeds any real cost sum
    int n; cin >> n;
    vector<int> q(n); for (auto &x : q) cin >> x;
    int m; cin >> m;
    vector<E> es;
    for (int i = 0; i < n; i++) es.push_back({n, i, BIG});
    for (int i = 0; i < m; i++) {
        int a, b; ll c; cin >> a >> b >> c;
        if (q[a - 1] > q[b - 1]) es.push_back({a - 1, b - 1, c});
    }
    ll res = dmst(n + 1, n, es);
    cout << ((res < 0 || res / BIG != 1) ? -1 : res % BIG) << "\n";
}

