#include <bits/stdc++.h>
using namespace std;
vector<int> p;
// fills p[0..n) with a permutation q such that i & q[i] == 0 for all i
void build(int n) {
    if (n <= 1) { if (n == 1) p[0] = 0; return; }
    int h = 1;
    while (2 * h <= n - 1) h *= 2;          // h <= n-1 < 2h
    for (int x = h; x < n; x++) { int y = 2 * h - 1 - x; p[x] = y; p[y] = x; }
    build(2 * h - n);                        // remaining lower values map among themselves
}
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int l, r; scanf("%d %d", &l, &r);
        int n = r - l + 1;
        p.assign(n, 0);
        build(n);
        // l = 0 here: sum of OR = sum(i) + sum(p_i) - sum(i & p_i) = 2 * sum(0..n-1)
        long long S = (long long)n * (n - 1) / 2;
        printf("%lld\n", 2 * S);
        for (int i = 0; i < n; i++) printf("%d ", p[i]);
        printf("\n");
    }
