#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// Can s = sum of coins 2^j (j in bits of m), each used at most N times?
// q = remaining value / 2^j; track the reachable interval [L,H] of q at each level.
bool feas(ll N, ll s, ll m) {
    ll L = s, H = s;
    for (int j = 0; j < 62; j++) {
        if ((m >> j) & 1) {
            ll x = max(0LL, L - N);
            L = (x + 1) / 2; H = H / 2;
        } else {
            if (L > H) return false;
            ll lo = (L + 1) / 2, hi = H / 2;   // only even q allowed
            L = lo; H = hi;
        }
        if (L > H) return false;
    }
    return L == 0;
}
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        ll s, m; scanf("%lld %lld", &s, &m);
        if (!feas(s, s, m)) { puts("-1"); continue; }
        ll lo = 1, hi = s;
        while (lo < hi) { ll mid = (lo + hi) / 2; if (feas(mid, s, m)) hi = mid; else lo = mid + 1; }
        printf("%lld\n", lo);
    }
}

