    while (t--) {
        int n; scanf("%d", &n);
        vector<int> a(n);
        for (auto &x : a) scanf("%d", &x);
        // value v (< m) can be produced by element x iff x == v or x > 2v (take b = x - v > v)
        auto feas = [&](int m) -> bool {
            vector<int> single(m, 0), enter(m, 0);
            for (int x : a) {
                if (x < m) single[x]++;
                if (x >= 1) enter[min((x - 1) / 2, m - 1)]++;
            }
            long long pool = 0;
            for (int v = m - 1; v >= 0; v--) {
                pool += enter[v];
                if (single[v] > 0) {
                    single[v]--;
                    if (v >= 1) enter[(v - 1) / 2]--;
                } else if (pool > 0) pool--;
                else return false;
            }
            return true;
        };
        int lo = 0, hi = n;
        while (lo < hi) { int mid = (lo + hi + 1) / 2; if (feas(mid)) lo = mid; else hi = mid - 1; }
        printf("%d\n", lo);
    }
}

