        vector<long long> all = a; all.insert(all.end(), b.begin(), b.end());
        sort(all.rbegin(), all.rend());
        all.erase(unique(all.begin(), all.end()), all.end());
        auto F = [&](long long r, long long c) -> long long {
            long long cA = 0, cB = 0, tot = 0, sum = 0;
            for (long long v : all) {
                bool inA = binary_search(a.begin(), a.end(), v);
                bool inB = binary_search(b.begin(), b.end(), v);
                if (tot >= r + c) break;
                if (inA && !inB) { if (cA < r) { cA++; tot++; sum += v; } }
                else if (inB && !inA) { if (cB < c) { cB++; tot++; sum += v; } }
                else { tot++; sum += v; }
            }
            return sum;
        };
        printf("%lld\n", max(F(n, m - 1), F(n - 1, m)));
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int t; scanf("%d", &t);
    while (t--) {
        int n; scanf("%d", &n);
        vector<long long> b(n);
        long long S = 0;
        for (auto &x : b) { scanf("%lld", &x); S += x; }
        if (S <= 0) { puts("-1"); continue; }
        multiset<long long> R(b.begin(), b.end());
        vector<long long> res;
        long long cur = 0;
        bool fail = false;
        while (!R.empty() && !fail) {
            long long M1 = *prev(R.end());
            long long M2 = R.size() >= 2 ? *prev(prev(R.end())) : 0;
            bool uniq = R.count(M1) == 1;
            auto ok = [&](long long d) {
                if (cur + d <= 0) return false;
                if (R.size() == 1) return true;
                long long other = (d == M1 && uniq) ? M2 : M1;
                return cur + d + other > 0;
            };
            long long lo = max(-cur, -cur - M1) + 1;   // non-max candidates above this always pass
            long long pick = LLONG_MIN; bool have = false;
            auto it = R.lower_bound(lo);
            if (it != R.end() && ok(*it)) { pick = *it; have = true; }
            else if (ok(M1)) { pick = M1; have = true; }
            if (!have) { fail = true; break; }
            cur += pick; res.push_back(cur);
            R.erase(R.find(pick));
        }
        if (fail) { puts("-1"); continue; }
        for (size_t i = 0; i < res.size(); i++) printf("%lld ", res[i]);
        printf("\n");
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int T; scanf("%d", &T);
    while (T--) {
        int n; scanf("%d", &n);
        vector<int> b(n);
        for (auto &x : b) scanf("%d", &x);
        // island p may hold treasure only if |i-p| >= b_i for every known i (open interval forbidden)
        vector<int> diff(n + 1, 0);
        for (int i = 0; i < n; i++) if (b[i] >= 1) {
            int l = max(0, i - b[i] + 1), r = min(n - 1, i + b[i] - 1);
            diff[l]++; diff[r + 1]--;
        }
        vector<char> A(n);
        int c = 0;
        for (int p = 0; p < n; p++) { c += diff[p]; A[p] = (c == 0); }
        const int INF = 1e9;
        vector<int> dist(n, INF);
        int last = -1;
        for (int p = 0; p < n; p++) { if (A[p]) last = p; if (last >= 0) dist[p] = p - last; }
        last = -1;
        for (int p = n - 1; p >= 0; p--) { if (A[p]) last = p; if (last >= 0) dist[p] = min(dist[p], last - p); }
        bool ok = false;
        for (int p = 0; p < n; p++) ok |= A[p];
        for (int i = 0; i < n && ok; i++) if (b[i] >= 0 && dist[i] != b[i]) ok = false;
        if (!ok) { puts("-1"); continue; }
        string s(n, '0');
        for (int p = 0; p < n; p++) if (A[p]) s[p] = '1';
        puts(s.c_str());
    }
}
